import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Icon, Dialog, EmptyState, StatusPill } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { workflow, runs, validation } from "./data.js";

const toast=(message)=>message&&html`<div class="p-workflows-toast" role="status">${message}</div>`;
function Header({action}){return html`<header class="p-workflows-head"><div><p>ORCHESTRATION</p><h1>Build workflows</h1><span>Multi-step pipelines across agents, conversations, and approval gates.</span></div><button class="p-workflows-primary" onClick=${action}><${Icon} name="plus"/> Add step</button></header>`}
function AddDialog({close,notify}){return html`<${Dialog} onClose=${close}><div class="p-workflows-dialog"><p>NEW STEP</p><h2>Choose a workflow step</h2>${[["scout","Investigate before execution"],["worker","Implement in a workspace"],["gate","Wait for human approval"],["parallel","Run independent work together"]].map(([type,copy])=>html`<button onClick=${()=>{notify(type+" step added to draft");close()}}><b>${type}</b><span>${copy}</span></button>`)}<button class="p-workflows-cancel" onClick=${close}>Cancel</button></div></${Dialog}>`}
function Runs({selected,setSelected}){return html`<aside class="p-workflows-runs"><header><span>RUN HISTORY</span><button aria-label="Start workflow" onClick=${()=>setSelected("run-284")}>Run now</button></header>${runs.map(run=>html`<button class=${selected===run.id?"on":""} onClick=${()=>setSelected(run.id)}><${StatusPill} status=${run.status}/><b>${run.id}</b><small>${run.when} · ${run.duration}</small></button>`)}</aside>`}
function Builder({notify}){const [step,setStep]=useState(workflow.steps[1]);const [dialog,setDialog]=useState(false);const [run,setRun]=useState("run-284");return html`<main class="e-page p-workflows-page"><${Header} action=${()=>setDialog(true)}/><div class="p-workflows-builder"><${Runs} selected=${run} setSelected=${setRun}/><section class="p-workflows-steps"><div class="p-workflows-summary"><b>${workflow.name}</b><span>${workflow.project} · ${workflow.budget} budget · retry twice</span></div>${workflow.steps.map((item,i)=>html`<button class=${step.id===item.id?"p-workflows-step on":"p-workflows-step"} onClick=${()=>setStep(item)}><span class="p-workflows-num">${i+1}</span><span class=${`p-workflows-type ${item.type}`}>${item.type}</span><span><b>${item.name}</b><small>${item.agent} · ${item.status}</small></span><${StatusPill} status=${item.status}/></button>`)}<button class="p-workflows-add-row" onClick=${()=>setDialog(true)}>+ Add branch or step</button></section><aside class="p-workflows-inspector"><p>STEP INSPECTOR</p><h2>${step.name}</h2><label>Assigned agent<select value=${step.agent}><option>atlas</option><option>beacon</option><option>forge</option><option>moss</option></select></label><label>Timeout<input value="20 minutes"/></label><label>On failure<select><option>Retry twice, then block</option><option>Continue to reviewer</option></select></label><div class="p-workflows-inspect-actions"><button onClick=${()=>notify("Step duplicated")}>Duplicate</button><button onClick=${()=>notify("Step settings saved")}>Save</button></div></aside></div>${dialog&&html`<${AddDialog} close=${()=>setDialog(false)} notify=${notify}/>`}</main>`}
function Canvas({notify}){const [selected,setSelected]=useState("build");const node=(id,title,kind)=>html`<button class=${`p-workflows-node ${id} ${selected===id?"on":""}`} onClick=${()=>setSelected(id)}><span>${kind}</span><b>${title}</b></button>`;return html`<main class="e-page p-workflows-page"><${Header} action=${()=>notify("Step palette opened")}/><div class="p-workflows-canvas-layout"><aside class="p-workflows-palette"><p>STEP PALETTE</p>${["Scout","Worker","Reviewer","Approval gate","Parallel branch"].map(x=>html`<button onClick=${()=>notify(x+" added to canvas")}>+ ${x}</button>`)}</aside><section class="p-workflows-canvas" aria-label="Workflow canvas"><svg viewBox="0 0 800 360" preserveAspectRatio="none"><path d="M150 93H280V93M390 93H485V93M590 93H700V210"/><path d="M390 105V255H700"/></svg>${node("scout","Scout signals","atlas")}${node("build","Implement", "beacon")}${node("review","Review", "forge")}${node("gate","Human approval", "gate")}${node("fallback","Retry / block", "branch")}</section><aside class="p-workflows-canvas-inspector"><p>SELECTED NODE</p><h2>${selected==="build"?"Implement":"Workflow node"}</h2><${StatusPill} status="running"/><p>On success, continue to review. On failure, retry twice before routing to the blocked branch.</p><button onClick=${()=>notify("Node changes saved")}>Save node</button></aside></div></main>`}
function Yaml({notify}){const [tab,setTab]=useState("Definition");const [empty,setEmpty]=useState(false);if(empty)return html`<main class="e-page p-workflows-page"><${Header} action=${()=>setEmpty(false)}/><${EmptyState}>No workflow selected. Create one to coordinate a new pipeline.</${EmptyState}></main>`;return html`<main class="e-page p-workflows-page"><${Header} action=${()=>notify("YAML step inserted")}/><div class="p-workflows-yaml-tabs"><button class=${tab==="Definition"?"on":""} onClick=${()=>setTab("Definition")}>Definition</button><button class=${tab==="Past run"?"on":""} onClick=${()=>setTab("Past run")}>Past run</button><button onClick=${()=>setEmpty(true)}>Empty state</button></div>${tab==="Definition"?html`<div class="p-workflows-yaml-layout"><section><p>workflow.yml</p><pre>name: release-readiness
project: durable/web
budget: $12.00
steps:
  - scout: release signals
  - worker: implement notes
  - reviewer: public changes
  - approval: human gate
on_error: retry(2) → blocked</pre></section><section class="p-workflows-preview"><p>RENDERED PATH</p>${workflow.steps.map(x=>html`<div><span></span><b>${x.name}</b><small>${x.type}</small></div>`)}</section><aside class="p-workflows-problems"><p>VALIDATION · 2</p>${validation.map(x=>html`<article><b>${x}</b><button onClick=${()=>notify("Opened validation location")}>Fix</button></article>`)}</aside></div>`:html`<section class="p-workflows-run-view"><header><div><p>RUN run-283</p><h2>Release readiness completed</h2></div><${StatusPill} status="done"/></header>${workflow.steps.map((x,i)=>html`<div><span class=${i===2?"p-workflows-live":""}></span><b>${x.name}</b><small>${i===2?"Completed in 3m 14s":"Completed"}</small></div>`)}</section>`}</main>`}
export default function WorkflowsPage(){const [message,setMessage]=useState("");const notify=x=>{setMessage(x);setTimeout(()=>setMessage(""),2200)};return html`<${PageVariants} variants=${[{key:"1",name:"Step builder",render:()=>html`<${Builder} notify=${notify}/>`},{key:"2",name:"Canvas",render:()=>html`<${Canvas} notify=${notify}/>`},{key:"3",name:"YAML & runs",render:()=>html`<${Yaml} notify=${notify}/>`}]}/>${toast(message)}`}
